        t.MapPut("/members/{id:guid}", async (Guid tenant, Guid id, MemberWriteRequest r, AppDb db, Access a, MembershipService service) => { await using var tx = await db.Database.BeginTransactionAsync(); await MembershipService.Lock(db, tenant); var m = await db.Memberships.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); bool self = await service.IsSelf(m); bool write = await a.Can(tenant, "members.write", m.ChapterId); if (!self && (!write||!await a.Can(tenant,"members.read",m.ChapterId))) throw new AccessDeniedException(); if (m.Revision != r.Revision) return Results.Conflict(new { title = "Member changed. Refresh before editing." }); if (r.ChapterId != m.ChapterId) throw new DomainException("Use the transfer workflow to change chapters"); if (!write && (r.Status != m.Status || r.CategoryId != m.CategoryId || r.Number != m.Number || (r.JoinedAt != null && r.JoinedAt != m.JoinedAt) || (r.EffectiveFrom != null && r.EffectiveFrom != m.EffectiveFrom) || (r.EndsAt != null && r.EndsAt != m.EndsAt))) throw new AccessDeniedException(); MembershipService.ValidateProfile(r.Profile); if (r.Privacy != null) { MembershipService.ValidatePrivacy(r.Privacy); m.Privacy = r.Privacy; } if (write) { if (m.PendingPayment && r.Status == "Active" && !await db.Set<MembershipRenewal>().AnyAsync(renewal => renewal.TenantId == tenant && renewal.MembershipId == id && db.Set<FinanceInvoice>().Any(i => i.TenantId == tenant && i.Id == renewal.InvoiceId && i.Status == "Issued" && i.Total > 0 && i.Paid >= i.Total))) throw new DomainException("Membership activates after confirmed payment"); if (r.CategoryId != m.CategoryId) { await service.Category(tenant, r.CategoryId); var previousKind = await db.MembershipCategories.Where(c => c.TenantId == tenant && c.Id == m.CategoryId).Select(c => c.Kind).SingleAsync(); var nextKind = await db.MembershipCategories.Where(c => c.TenantId == tenant && c.Id == r.CategoryId).Select(c => c.Kind).SingleAsync(); 