untAsync(x => x.JoinedAt >= previous && x.JoinedAt < month); var currentNew = await q.CountAsync(x => x.JoinedAt >= month); return Results.Ok(new { total = await q.CountAsync(), uniquePersons = await q.Select(x => x.PersonId).Distinct().CountAsync(), active = await q.CountAsync(x => x.Status == "Active" && x.EffectiveFrom <= now && (x.EndsAt == null || x.EndsAt > now)), inactive = await q.CountAsync(x => x.Status == "Inactive"), pending = await db.MemberApplications.CountAsync(x => x.TenantId == tenant && units.Contains(x.ChapterId) && (x.Status == "Submitted" || x.Status == "Under Review")), newThisMonth = currentNew, transfers = await db.MembershipTransfers.CountAsync(x => x.TenantId == tenant && (units.Contains(x.SourceId) || units.Contains(x.DestinationId))), requiredPositions=required,chapterCount,activeChapterCount,regionCount,vacancies=required==0?(int?)null:Math.Max(0,required*activeChapterCount-occupied),retentionPercent = baseline == 0||unknownHistory ? (double?)null : Math.Round(retained * 100.0 / baseline, 2), growthPercent = priorNew == 0 ? (double?)null : Math.Round((currentNew - priorNew) * 100.0 / priorNew, 2), byChapter = await q.GroupBy(x => x.ChapterId).Select(g => new { id = g.Key, name = db.Units.Where(u => u.Id == g.Key).Select(u => u.Name).First(), members = g.Count(), active = g.Count(m => m.Status == "Active"&&m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now)) }).ToListAsync(), categories = await q.GroupBy(x => x.CategoryId).Select(g => new { id = g.Key, name = db.MembershipCategories.Where(c => c.Id == g.Key).Select(c => c.Name).First(), count = g.Count() }).ToListAsync(), leadership = await db.OfficerAppointments.CountAsync(x => x.TenantId == tenant && (x.UnitId == null || units.Contains(x.UnitId.Value)) && x.Status == "Approved" && x.StartsAt <= now && x.EndsAt > now&&db.Memberships.Any(m=>m.Id==x.MembershipId&&m.Status=="Active"&&m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now))) }); });
